"""Documentación pública en README.md."""
import argparse
import html
import json
from pathlib import Path
import shutil
import zipfile
ROOT = Path(__file__).resolve().parents[1]

def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--salida', required=True)
    p.add_argument('--codigo', required=True)
    p.add_argument('--experimento', default=str(ROOT / 'outputs/experimento_v4_01'))
    p.add_argument('--nativa', default=str(ROOT / 'outputs/validacion_nativa_v4_01/validacion_publica_25hz.json'))
    args = p.parse_args()
    source, out = (Path(args.experimento), Path(args.salida))
    r = json.loads((source / 'comparacion_publica.json').read_text(encoding='utf-8'))
    native = json.loads(Path(args.nativa).read_text(encoding='utf-8'))
    if r['protocolo']['version'] != 4 or r['protocolo']['gt_concurso_usado'] is not False or set(r['test']) != {'J03WPY', 'J03WQQ', 'J03WR9'} or (native['gt_concurso_usado'] is not False):
        raise ValueError('Solo se admite el experimento público fijado')
    if out.exists():
        raise FileExistsError('El informe necesita destino nuevo')
    with zipfile.ZipFile(args.codigo) as z:
        if z.testzip() is not None or any((n.startswith(('data/', 'outputs/', '.git/')) or n.endswith(('.csv', '.xml', '.mp4', '.npz', '.ipynb')) for n in z.namelist())):
            raise ValueError('Código no separado de datos')
    out.mkdir(parents=True, exist_ok=False)
    model = json.loads((source / 'modelo_v4.json').read_text(encoding='utf-8'))
    rows = []
    for game, result in r['test'].items():
        for scenario, score in result['escenarios'].items():
            rows.append([game, scenario, *[f'{score[v][k]:.4f}' for k in ['spellF1', 'macroF1'] for v in ['v3', 'v4']], f"{score['v3']['por_clase']['D']['f1']:.4f}", f"{score['v4']['por_clase']['D']['f1']:.4f}"])
    native_rows = []
    for game, scores in native['resultados'].items():
        key = 'macroF1' if game.startswith('DFL') else 'macroF1_apoyo'
        native_rows.append([game, 'Completo' if game.startswith('DFL') else 'Apoyo débil', f"{scores['v3'][key]:.4f}", f"{scores['v4'][key]:.4f}"])
    table = '\n'.join(('| ' + ' | '.join(row) + ' |' for row in rows))
    ntable = '\n'.join(('| ' + ' | '.join(row) + ' |' for row in native_rows))
    d = r['decision']
    md = f"""# veriana — Revisión de entrega v4\n\n15 de noviembre de 2026. Candidata recomendada por el protocolo externo: **{d['candidata_recomendada']}**.\nLa puntuación del partido del concurso sigue desconocida.\n\n## Qué cambió\n\n- Clasificador supervisado de juego detenido con 13 variables de movimiento y organización espacial.\n  Usa {model['pausa_v4']['referencias']:,} referencias externas y {len(model['pausa_v4']['arboles'])} árboles simples.\n- Control H/A ampliado con tiempo de acceso al balón: {model['control_v4']['referencias']:,} referencias\n  y once variables antisimétricas. Se combinan partidos DFL y SkillCorner y se conserva la base v3.\n- Tipos de saque, conflictos y equipo desconocido explícitos, más candidatos geométricos de banda.\n  Se implementó el prior de ejecutante y se probó como ablación. No quedó activo en la seleccionada.\n- Herramientas de homografía para proyectar líneas/pies y asociar ejecutantes, con pruebas sintéticas.\n  No hay un detector visual activado ni fusión de píxeles en esta entrega.\n\nOpciones congeladas: `{json.dumps(model['opciones'], ensure_ascii=False)}`.\nLa velocidad se mide a escala de 0,2 s para transferir entre desarrollo a 5 Hz y producción a 25 Hz.\nLa ausencia del balón no entra como variable de clase D; las referencias y eventos nunca son inputs.\n\n## Test reservado de otros partidos DFL, a 5 Hz\n\n| Partido | Escenario | Spell v3 | Spell v4 | Macro v3 | Macro v4 | D F1 v3 | D F1 v4 |\n|---|---|---:|---:|---:|---:|---:|---:|\n{table}\n\nGanancia media de spellF1: **{d['ganancia_media_spellF1'] * 100:+.2f} puntos porcentuales**.\nGanancia media de macroF1: **{-d['caida_media_macroF1'] * 100:+.2f} puntos porcentuales**.\nSe calculan con el evaluador oficial sobre referencias DFL externas, con otra convención y a 5 Hz.\nNo son resultados oficiales del concurso ni una garantía de generalización.\n\nLa partición y el criterio se guardaron antes de entrenar. El modelo y su hash se congelaron\nantes de evaluar J03WPY/J03WQQ/J03WR9. No se reajustó después de verlos. Los tres ya se utilizaron\ny no pueden presentarse como un nuevo test ciego en futuras iteraciones.\n\n## Guardia a 25 fps, frecuencia de la entrega\n\n| Fuente de desarrollo conocida | Referencias | Macro v3 | Macro v4 |\n|---|---|---:|---:|\n{ntable}\n\nEsta comprobación verifica el cambio de frecuencia sin volver a entrenar. No constituye otro\ntest independiente. Metrica Game 2 ya era desarrollo y sus referencias son débiles.\n\n## Fuentes y saques de banda\n\nEl corpus externo disponible suma 15 partidos: dos Metrica, seis SkillCorner y siete DFL/IDSSE.\nDFL publica BallStatus activo/inactivo y BallPossession. Son respuestas para entrenar/evaluar,\nnunca variables de entrada. Train DFL: J03WMX/J03WN1/J03WOH. Desarrollo: J03WOY. Test: los tres de\nla tabla. Los modelos de base y control también conservan las particiones previas de Metrica y\nSkillCorner. Todos los partidos son distintos al del concurso, con procedencia y hashes fijados.\n\nSegún DATA.md oficial, existen 26 tags Throw-in, todos con Team=N/A. No se inventa su equipo.\nEl nuevo módulo conserva el tipo, puede acumular evidencia del ejecutante junto a la lateral y\nevita invertir automáticamente al último poseedor. Las ventanas de tag no se copian como D.\nDurante la espera, saber qué equipo sacará no significa posesión viva. El prior adicional quedó\nfuera de la candidata porque no mejoró el promedio de desarrollo.\n\n## Límites y alcance de entrega\n\nEl tracking DFL es más limpio y revisado que el del reto. Sus etiquetas, límites de juego detenido\ny definición de control pueden diferir. El estrés simula oclusiones y errores, pero no garantiza\nreplicar todos los fallos del ATD. Los saltos se rechazan antes de derivar velocidades y ninguna\nderivada cruza una mitad. La homografía no reconstruye altura de balón en manos o en vuelo.\n\nSoccerNet/PathCRF quedan como investigación futura: incorporar un detector visual o un experto de\nrutas de posesión exige adaptación y validación adicionales. La entrega utiliza NumPy/pandas,\nsin GPU, servicios remotos, descargas durante inferencia ni anotaciones manuales.\n\nLa candidata anterior v3 y sus artefactos se conservan. El CSV y los registros del concurso\npermanecen en una carpeta local privada. El código se empaqueta aparte y debe reproducir el\nCSV byte a byte y superar el validador oficial. Esta carpeta de revisión solo contiene código,\ndocumentación y resultados de otros partidos públicos.\n\n## Archivos y reproducción\n\n- `codigo_publicable.zip`: código, dependencias, pruebas, modelo externo y documento técnico.\n- `comparacion_publica.json`: resultados externos completos y ablaciones.\n- `protocolo_previo.json`, `seleccion_antes_test.json`: protocolo y elección antes del test.\n- `validacion_publica_25hz.json`: guardia de ejecución nativa.\n\nDesde el código extraído y con autorización local:\n\n```powershell\npython -m pip install -r requirements-pipeline.txt\npython reproducir_entrega.py --datos "D:\\bundle-local" --salida veriana.csv --autorizar-datos-restringidos\n```\n\nSe debe publicar la rama de código para revisión del equipo y usar el canal oficial para enviar\nCSV/documento. El formulario oficial no se ha enviado. Los cinco minutos oficiales no se usaron\npara entrenamiento, ajuste o selección.\n\nFuentes: [DFL/IDSSE](https://pmc.ncbi.nlm.nih.gov/articles/PMC11787359/),\n[Metrica Sports](https://github.com/metrica-sports/sample-data),\n[SkillCorner](https://github.com/SkillCorner/opendata),\n[reglas del concurso](https://github.com/metrica-sports/more-than-a-hack-2027/blob/main/RULES.md).\n"""
    (out / 'INFORME_VERIANA.md').write_text(md, encoding='utf-8')

    def htable(headers, values):
        return '<div class="scroll"><table><thead><tr>' + ''.join(('<th>' + html.escape(x) + '</th>' for x in headers)) + '</tr></thead><tbody>' + ''.join(('<tr>' + ''.join(('<td>' + html.escape(x) + '</td>' for x in row)) + '</tr>' for row in values)) + '</tbody></table></div>'
    page = f"""<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>veriana · Entrega v4</title><style>\n*{{box-sizing:border-box}}body{{margin:0;background:#eef3f5;color:#17313c;font:17px/1.6 'Segoe UI',Arial,sans-serif}}header{{background:#102e39;color:white;padding:55px max(25px,calc((100vw - 1100px)/2))}}header p{{color:#cfe6e7;max-width:820px}}h1{{font-size:clamp(36px,6vw,62px);line-height:1.1;margin:15px 0}}main{{max-width:1140px;padding:20px;margin:auto}}section{{background:white;border:1px solid #dae4e8;border-radius:12px;padding:30px 34px;margin:22px 0}}h2{{font-size:28px;line-height:1.2;margin:0 0 22px}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}}.stat{{padding:22px;background:#edf9f1;border-radius:8px}}.stat b{{display:block;font-size:36px;color:#08784e}}.stat span,.small{{font-size:14px}}.scroll{{overflow-x:auto}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:12px;border-bottom:1px solid #d7e2e7;white-space:nowrap;text-align:left}}th{{background:#edf4f6}}.note{{background:#fff7e3;padding:18px;border-left:4px solid #dbab32}}a{{color:#08764f}}.eyebrow{{font-size:13px;letter-spacing:2px;color:#8de8b8}}li{{margin:9px 0}}@media(max-width:750px){{.grid{{grid-template-columns:1fr}}section{{padding:23px 18px}}}}@media print{{body{{background:white}}section{{break-inside:avoid;border:0}}header{{background:white;color:#17313c;padding:10px}}header p{{color:#17313c}}}}</style></head><body><header><div class="eyebrow">MORE THAN A HACK 2027 · VERIANA · FASE 1</div><h1>v4: mejor control<br>y detección de paradas</h1><p>Candidata elegida con otros partidos públicos. El score oficial del concurso sigue desconocido.</p></header><main>\n<section><h2>Resultado del test externo reservado</h2><div class="grid"><div class="stat"><b>{d['ganancia_media_spellF1'] * 100:+.2f} pp</b><span>spellF1 medio frente a v3</span></div><div class="stat"><b>{-d['caida_media_macroF1'] * 100:+.2f} pp</b><span>macroF1 medio frente a v3</span></div><div class="stat"><b>3</b><span>partidos DFL reservados antes del ajuste</span></div></div><p>El protocolo eligió <strong>{r['variante_congelada']}</strong>. La pausa aprendida mejora la recuperación de juego detenido. La mezcla parcial superó al reemplazo completo.</p><div class="note">Son métricas de otros partidos, a 5 Hz y con referencias de otro proveedor. No representan la puntuación del concurso.</div></section>\n<section><h2>Mejora por partido y escenario</h2>{htable(['Partido', 'Escenario', 'Spell v3', 'Spell v4', 'Macro v3', 'Macro v4', 'D F1 v3', 'D F1 v4'], rows)}<p class="small">Original y estrés con semillas fijas. El modelo quedó congelado antes de evaluar estos tres encuentros.</p></section>\n<section><h2>Comprobación a los 25 fps de la entrega</h2>{htable(['Fuente conocida', 'Referencias', 'Macro v3', 'Macro v4'], native_rows)}<p class="small">Guardia de desarrollo para la frecuencia nativa, sin reentrenamiento. Metrica usa apoyo débil H/A/D y no es otro test ciego.</p></section>\n<section><h2>Qué incluye la candidata</h2><ul><li>Control H/A con once variables, incluyendo tiempo de acceso al balón</li><li>Pausa supervisada con 13 señales de movimiento y organización espacial</li><li>HMM offline con evidencia anterior y posterior, máscaras y separación entre mitades</li><li>Tipos de saque y equipo desconocido explícitos, con prior de ejecutante disponible como ablación</li><li>Modelo y dependencias congelados para inferencia local sin GPU ni servicios externos</li></ul><p>El prior extra de equipo en saques no quedó activo: no mejoró desarrollo. Las utilidades de homografía están verificadas; un detector visual y la fusión de píxeles requieren una validación propia.</p></section>\n<section><h2>Reglas y límites visibles</h2><p>El entrenamiento y selección usan otros partidos públicos. No se utilizaron los cinco minutos oficiales, anotaciones manuales ni datos humanos del partido del concurso. El CSV, vídeo, tracking y diagnósticos privados quedan fuera de esta carpeta.</p><p>El tracking DFL es más limpio y tiene otras convenciones. Las simulaciones de error no eliminan el cambio de dominio. Se conserva v3 como respaldo.</p></section>\n<section><h2>Material para revisar y entregar</h2><p><a href="INFORME_VERIANA.md">Informe completo</a> · <a href="codigo_publicable.zip">Código y modelo</a> · <a href="comparacion_publica.json">Resultados externos</a> · <a href="protocolo_previo.json">Protocolo previo</a> · <a href="validacion_publica_25hz.json">Guardia 25 fps</a></p><p>La carpeta de revisión contiene solo fuentes y resultados externos públicos. El CSV para el formulario está separado en la carpeta privada de entrega. El envío oficial sigue pendiente.</p></section></main></body></html>"""
    (out / 'INFORME_VERIANA.html').write_text(page, encoding='utf-8')
    for name in ['comparacion_publica.json', 'protocolo_previo.json', 'seleccion_antes_test.json']:
        shutil.copyfile(source / name, out / name)
    shutil.copyfile(args.nativa, out / 'validacion_publica_25hz.json')
    shutil.copyfile(args.codigo, out / 'codigo_publicable.zip')
    with zipfile.ZipFile(out / 'veriana_revision_equipo_v4.zip', 'x', compression=zipfile.ZIP_DEFLATED) as z:
        for path in sorted(out.iterdir()):
            if path.name != 'veriana_revision_equipo_v4.zip':
                z.write(path, path.name)
    print('Revisión v4 generada exclusivamente con resultados externos públicos')
if __name__ == '__main__':
    main()
